void validate_daxa_calibration_pose(const std::array<double,16>& t){
    for(double value:t)require(std::isfinite(value),"finite calibration transform required");
    // Match numpy allclose/isclose defaults used in types.py::validate_pose.
    auto close=[](double actual,double expected,double atol){return std::abs(actual-expected)<=atol+1e-5*std::abs(expected);};
    for(unsigned i=0;i<4;++i)require(close(t[12+i],i==3?1.:0.,1e-8),"invalid calibration affine bottom row");
    for(unsigned row=0;row<3;++row)for(unsigned column=0;column<3;++column){double dot=0;for(unsigned k=0;k<3;++k)dot+=t[k*4+row]*t[k*4+column];require(close(dot,row==column?1.:0.,1e-6),"calibration rotation must be orthonormal");}
    double determinant=t[0]*(t[5]*t[10]-t[6]*t[9])-t[1]*(t[4]*t[10]-t[6]*t[8])+t[2]*(t[4]*t[9]-t[5]*t[8]);require(close(determinant,1.,1e-6),"calibration rotation determinant must be +1");double norm=std::sqrt(t[3]*t[3]+t[7]*t[7]+t[11]*t[11]);require(norm>0,"calibration stereo baseline must be positive");
}
MetricCalibration DaxaRectification::metric_calibration()const{
    require(geometry.has_value(),"metric processing requires retained calibrated geometry");auto const& g=*geometry;
    require(g.original_identity==original_identity&&g.rectified_identity==rectified_identity,"metric geometry calibration identity mismatch");
    for(auto const& eye:g.original.eyes)require(eye.width==eye_width&&eye.height==source_height,"metric original camera dimensions mismatch");
    for(auto const& eye:g.rectified.eyes)require(eye.width==width&&eye.height==height,"metric rectified camera dimensions mismatch");
    return g.metric_calibration();
}
